"use client";

import * as React from "react";
import { HANDLE_ART as ART, HANDLE_GEO as GEO } from "./handle-art";
import { Input } from "./input";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * USERNAME: a penguin holds up the name you want
 *
 *   write    as you type, the name appears on Handle's sign,
 *            letter by letter
 *   free     check() says it's available: he beams, a green tick
 *            lands on the corner of his sign
 *   taken    it isn't: his sign goes blank and his face falls,
 *            and its owner, a smug penguin in a scarf, slides in
 *            hugging a sign with your name on it ("@ana is mine")
 *   try      suggestions come back as chips; one tap writes it
 *   claim    Claim @name → Claiming → Claimed
 *
 * check(name, signal) and onClaim(name) are yours; the field
 * lowercases as you type and keeps to the characters you allow.
 * ───────────────────────────────────────────────────────── */

export interface UsernameProps {
  /** Is the name free? Aborted when a newer name starts. Suggestions show when it isn't. */
  check: (
    name: string,
    signal: AbortSignal,
  ) => Promise<{ available: boolean; suggestions?: string[] }>;
  /** Keep the name; throw to say why not. */
  onClaim: (name: string) => Promise<unknown>;
  defaultValue?: string;
  minLength?: number;
  maxLength?: number;
  /** Characters allowed (the whole name is tested). */
  pattern?: RegExp;
  /** Says what's allowed when the pattern fails. */
  patternHint?: string;
  /** "@", or your domain ("relay.app/"). */
  prefix?: string;
  title?: string;
  /** What the penguin is called in his lines. */
  name?: string;
  className?: string;
}

type Phase =
  "empty" | "short" | "invalid" | "checking" | "free" | "taken" | "error";

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface: an ice floe's soft glow under the penguins, and faint snow. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(60% 40% at 50% 100%, ${mix(PF, 26)} 0%, transparent 70%)`,
    `linear-gradient(175deg, transparent 40%, ${mix("black", 20)} 100%)`,
    `radial-gradient(circle, ${mix(PF, 28)} 0 1px, transparent 1.5px)`,
    `radial-gradient(circle, ${mix(PF, 18)} 0 1px, transparent 1.5px)`,
  ].join(", "),
  backgroundSize: "auto, auto, 46px 38px, 31px 27px",
  backgroundPosition: "0 0, 0 0, 0 0, 14px 9px",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const LIT: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, ${mix(PF, 16)}, transparent 60%)`,
  boxShadow: `inset 0 1px 0 ${mix(PF, 32)}, inset 0 0 0 1px ${mix("black", 10)}`,
};
const INK = "oklch(0.25 0.02 260)";

/* the scene, drawn at 364 × 176 and scaled to the stage */
const W = 364;
const H = 176;
const GROUND = 172;
const OURS = { x: 118, h: 124 };
const OWNER = { x: 272, out: W + 80, h: 124 };
type Pose = "hope" | "joy" | "sad" | "owner";

/** A penguin, standing with its feet at (x, GROUND), with `text` written on its sign. */
function Penguin({
  pose,
  x,
  h,
  text,
  tick,
  style,
}: {
  pose: Pose;
  x: number;
  h: number;
  text: string;
  tick?: boolean;
  style?: React.CSSProperties;
}) {
  const g = GEO[pose];
  const k = h / g.h;
  const w = g.w * k;
  const b = g.board;
  const len = Math.max(1, text.length);
  const font = Math.min(17, ((b.w * k * 0.82) / len) * 1.6);
  return (
    <div
      className="absolute left-0 top-0"
      style={{
        transform: `translate(${x - w / 2}px, ${GROUND - h}px)`,
        width: w,
        height: h,
        ...style,
      }}
    >
      <img
        src={ART[pose]}
        alt=""
        draggable={false}
        className="pointer-events-none absolute inset-0 size-full max-w-none select-none"
      />
      <div
        className="absolute flex items-center justify-center whitespace-nowrap font-semibold tracking-[-0.02em]"
        style={{
          left: (b.x - b.w / 2) * k,
          top: (b.y - b.h / 2) * k,
          width: b.w * k,
          height: b.h * k,
          transform: `rotate(${b.angle}deg)`,
          color: INK,
          fontSize: font,
        }}
      >
        <TextMorph>{text || " "}</TextMorph>
        <span
          className="absolute -right-1.5 -top-1.5 grid size-[18px] place-items-center rounded-full text-white"
          style={{
            background: "var(--color-emerald-500, oklch(0.7 0.16 162))",
            opacity: tick ? 1 : 0,
            transform: tick
              ? "scale(1) rotate(0deg)"
              : "scale(0.3) rotate(-30deg)",
            transition:
              "opacity 200ms, transform 420ms cubic-bezier(0.34,1.36,0.64,1)",
          }}
        >
          <svg viewBox="0 0 16 16" className="size-3" fill="none">
            <path
              d="M3.8 8.3 6.6 11 12.2 5"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </span>
      </div>
    </div>
  );
}

export function Username({
  check,
  onClaim,
  defaultValue = "",
  minLength = 3,
  maxLength = 20,
  pattern = /^[a-z0-9_]+$/,
  patternHint = "Letters, numbers and _ only.",
  prefix = "@",
  title = "Pick a username",
  name = "Handle",
  className = "",
}: UsernameProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const [value, setValue] = React.useState(defaultValue.toLowerCase());
  const [result, setResult] = React.useState<{
    name: string;
    available: boolean;
    suggestions: string[];
  } | null>(null);
  const [failed, setFailed] = React.useState<string | null>(null);
  const [claim, setClaim] = React.useState<{
    status: ActionStatus;
    error?: string;
  }>({ status: "idle" });
  const checkRef = React.useRef(check);
  React.useEffect(() => {
    checkRef.current = check;
  });

  const valid = value.length >= minLength && pattern.test(value);
  React.useEffect(() => {
    if (!valid) return;
    const ctrl = new AbortController();
    const timer = window.setTimeout(() => {
      checkRef.current(value, ctrl.signal).then(
        (r) =>
          !ctrl.signal.aborted &&
          setResult({
            name: value,
            available: r.available,
            suggestions: r.suggestions ?? [],
          }),
        () => !ctrl.signal.aborted && setFailed(value),
      );
    }, 380);
    return () => {
      window.clearTimeout(timer);
      ctrl.abort();
    };
  }, [value, valid]);

  const known = result && result.name === value ? result : null;
  const phase: Phase = !value
    ? "empty"
    : !pattern.test(value)
      ? "invalid"
      : value.length < minLength
        ? "short"
        : failed === value
          ? "error"
          : !known
            ? "checking"
            : known.available
              ? "free"
              : "taken";
  const claimed = claim.status === "success";
  const pose: Pose =
    claimed || phase === "free"
      ? "joy"
      : phase === "taken" || phase === "invalid"
        ? "sad"
        : "hope";
  const handle = `${prefix}${value}`;
  const mood = claimed
    ? `Hello, ${handle}`
    : phase === "free"
      ? `${handle} is all yours`
      : phase === "taken"
        ? `“${handle} is mine.”`
        : phase === "checking"
          ? `${name} is asking around`
          : phase === "invalid"
            ? `${name} can’t write that`
            : phase === "short"
              ? "A little longer"
              : phase === "error"
                ? `${name} couldn’t check`
                : `${name} will hold it up`;

  const set = (next: string) => {
    setValue(next.toLowerCase().slice(0, maxLength));
    if (claim.status !== "idle" && claim.status !== "pending")
      setClaim({ status: "idle" });
  };

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (phase !== "free" || claim.status === "pending" || claimed) return;
    setClaim({ status: "pending" });
    try {
      await onClaim(value);
      setClaim({ status: "success" });
    } catch (err) {
      setClaim({
        status: "error",
        error:
          err instanceof Error && err.message
            ? err.message
            : "Couldn’t claim that. Try again.",
      });
    }
  };

  const fade = reduced
    ? "none"
    : `transform 520ms cubic-bezier(0.22,1,0.36,1), opacity 300ms ${EASE_OUT}`;
  const ownerIn = phase === "taken";
  const error =
    phase === "invalid"
      ? patternHint
      : phase === "error"
        ? "Couldn’t check that name. Try again."
        : claim.status === "error"
          ? claim.error
          : undefined;

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={CARD}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Scene>
            {(["hope", "joy", "sad"] as const).map((p) => (
              <Penguin
                key={p}
                pose={p}
                x={OURS.x}
                h={OURS.h}
                text={phase === "taken" ? "" : value ? handle : prefix}
                tick={p === "joy" && (phase === "free" || claimed)}
                style={{
                  opacity: p === pose ? 1 : 0,
                  transition: reduced ? "none" : `opacity 220ms ${EASE_OUT}`,
                }}
              />
            ))}
            {/* the one who already has it */}
            <Penguin
              pose="owner"
              x={ownerIn ? OWNER.x : OWNER.out}
              h={OWNER.h}
              text={known && !known.available ? `${prefix}${known.name}` : ""}
              style={{ opacity: ownerIn ? 1 : 0, transition: fade }}
            />
          </Scene>
          <p className="absolute left-3.5 top-3 z-10 max-w-[70%] text-[12.5px] font-medium text-primary-foreground/85">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        <form className="px-3 pb-1 pt-3" onSubmit={submit} noValidate>
          <h2
            id={`${baseId}-title`}
            className="text-[15px] font-medium tracking-[-0.01em]"
          >
            {title}
          </h2>
          <p className="mt-0.5 text-[12.5px] text-muted-foreground">
            {minLength} to {maxLength} characters. You can change it later.
          </p>
          <Input
            className="mt-3"
            aria-label="Username"
            leading={<span className="text-[13.5px]">{prefix}</span>}
            placeholder="yourname"
            value={value}
            onValueChange={set}
            autoComplete="username"
            autoCapitalize="off"
            spellCheck={false}
            maxLength={maxLength}
            error={error}
            hint={
              phase === "taken"
                ? "Taken. Try one of these:"
                : phase === "free"
                  ? "Available."
                  : undefined
            }
          />
          {phase === "taken" && known && known.suggestions.length > 0 && (
            <div
              className="mt-2 flex flex-wrap gap-1.5"
              aria-label="Suggestions"
            >
              {known.suggestions.slice(0, 4).map((s, i) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => set(s)}
                  className="h-7 cursor-pointer rounded-full border border-border bg-background px-2.5 text-[12.5px] hover:bg-accent"
                  style={
                    reduced
                      ? undefined
                      : {
                          animation: `ui-fade-up 320ms ${EASE_OUT} ${i * 50}ms backwards`,
                        }
                  }
                >
                  {prefix}
                  {s}
                </button>
              ))}
            </div>
          )}
          <StatusButton
            type="submit"
            status={claim.status}
            labels={{
              idle: phase === "free" ? `Claim ${handle}` : "Claim",
              pending: "Claiming",
              success: "Claimed",
              error: "Try again",
            }}
            disabled={
              phase !== "free" && claim.status !== "pending" && !claimed
            }
            className="mt-3 h-10 w-full text-[13.5px] disabled:bg-[color-mix(in_oklab,var(--foreground)_7%,transparent)] disabled:text-muted-foreground"
            style={
              phase === "free" && claim.status !== "error" ? LIT : undefined
            }
          />
        </form>
      </div>
      <span className="sr-only" role="status">
        {phase === "free"
          ? `${handle} is available.`
          : phase === "taken"
            ? `${handle} is taken.`
            : claimed
              ? `${handle} is yours.`
              : ""}
      </span>
    </section>
  );
}

/** The stage's scene, drawn at 364 × 176 and scaled to fit. */
function Scene({ children }: { children: React.ReactNode }) {
  const host = React.useRef<HTMLDivElement>(null);
  const scene = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const h = host.current;
    const s = scene.current;
    if (!h || !s) return;
    const fit = () =>
      s.style.setProperty("transform", `scale(${h.clientWidth / W})`);
    fit();
    const ro = new ResizeObserver(fit);
    ro.observe(h);
    return () => ro.disconnect();
  }, []);
  return (
    <div
      ref={host}
      aria-hidden="true"
      className="relative w-full"
      style={{ aspectRatio: `${W} / ${H}` }}
    >
      <div
        ref={scene}
        className="absolute left-0 top-0 origin-top-left"
        style={{ width: W, height: H }}
      >
        {children}
      </div>
    </div>
  );
}

export default Username;

/* Handle's art: an illustrated penguin with a blank sign, hopeful, overjoyed and let down, and the smug penguin who already has your name. As WebP data URIs so one install brings everything; sizes in each image's own pixels, and the sign's middle, size and tilt so a name can be written on it. */

export const HANDLE_ART = {
  hope: "data:image/webp;base64,",
  joy: "data:image/webp;base64,",
  sad: "data:image/webp;base64,",
  owner:
    "data:image/webp;base64,",
};

export const HANDLE_GEO = {
  hope: {
    w: 193,
    h: 241,
    board: { x: 96, y: 154.7, w: 140.1, h: 70.8, angle: 0 },
  },
  joy: {
    w: 198,
    h: 244,
    board: { x: 98.5, y: 139.9, w: 152.5, h: 73.1, angle: -2.9 },
  },
  sad: {
    w: 186,
    h: 248,
    board: { x: 93.2, y: 165.9, w: 125.8, h: 66, angle: 0 },
  },
  owner: { w: 208, h: 250, board: { x: 100, y: 150, w: 92, h: 66, angle: -8 } },
} as const;

"use client";

import * as React from "react";
import {
  Field,
  fieldSurface,
  setNativeValue,
  useFieldIds,
  useShake,
  type FieldSize,
} from "./imported-field";
import {
  EASE_OUT,
  INTERACTION_FOCUS,
  interactionIcon,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * INPUT: a one-line field
 *
 *   rest     a thin line pill; hover darkens the line
 *   focus    the line turns to the ring with a 3px halo
 *   typing   a clear button folds in once there is text and
 *            folds away when it's gone (it hands focus back)
 *   error    the line turns red, the hint gives way to the
 *            error and the field shakes once
 * ───────────────────────────────────────────────────────── */

export interface InputProps extends Omit<
  React.InputHTMLAttributes<HTMLInputElement>,
  "size"
> {
  label?: React.ReactNode;
  hint?: React.ReactNode;
  /** Shows red and replaces the hint. */
  error?: React.ReactNode;
  /** An icon or text before the value. */
  leading?: React.ReactNode;
  /** An icon, text or button after the value. */
  trailing?: React.ReactNode;
  /** A button that empties the field once it has text. */
  clearable?: boolean;
  /** 28px or 36px tall. */
  size?: FieldSize;
  /** Called with the new text on every change. */
  onValueChange?: (value: string) => void;
  ref?: React.Ref<HTMLInputElement>;
  /** Class for the outer column. */
  className?: string;
  /** Class for the input element itself. */
  inputClassName?: string;
}

function ClearIcon() {
  return (
    <svg viewBox="0 0 16 16" fill="none" className="size-3.5">
      <path
        d="M4.5 4.5l7 7M11.5 4.5l-7 7"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Input({
  label,
  hint,
  error,
  leading,
  trailing,
  clearable,
  size = "md",
  onValueChange,
  ref,
  id,
  className = "",
  inputClassName = "",
  value,
  defaultValue,
  onChange,
  disabled,
  required,
  ...props
}: InputProps) {
  const reduced = useInteractionReducedMotion();
  const ids = useFieldIds(id);
  const inner = React.useRef<HTMLInputElement>(null);
  const [text, setText] = React.useState(String(defaultValue ?? ""));
  const current = value !== undefined ? String(value) : text;
  const shakeRef = useShake<HTMLDivElement>(!!error);
  const sm = size === "sm";
  const showClear = !!clearable && current.length > 0 && !disabled;

  const setRefs = (el: HTMLInputElement | null) => {
    inner.current = el;
    if (typeof ref === "function") ref(el);
    else if (ref)
      (ref as React.RefObject<HTMLInputElement | null>).current = el;
  };

  const describedBy =
    [hint && !error ? ids.hint : null, error ? ids.error : null]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <Field
      id={ids.id}
      label={label}
      hint={hint}
      error={error}
      required={required}
      className={className}
    >
      <div
        ref={shakeRef}
        className={`${fieldSurface({ invalid: !!error, disabled })} ${sm ? "h-7 text-[16px] sm:text-[12.5px]" : "h-9 text-[16px] sm:text-[13.5px]"}`}
      >
        {leading && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pl-2.5" : "pl-3.5"} [&_svg]:size-3.5`}
          >
            {leading}
          </span>
        )}
        <input
          ref={setRefs}
          id={ids.id}
          value={value}
          defaultValue={defaultValue}
          disabled={disabled}
          required={required}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
          onChange={(e) => {
            if (value === undefined) setText(e.target.value);
            onChange?.(e);
            onValueChange?.(e.target.value);
          }}
          className={`h-full min-w-0 flex-1 bg-transparent outline-none placeholder:text-muted-foreground/70 ${leading ? "pl-2" : sm ? "pl-3" : "pl-4"} ${trailing || clearable ? "pr-1" : sm ? "pr-3" : "pr-4"} ${inputClassName}`}
          {...props}
        />
        {clearable && (
          // The clear button folds its own width open, so the text never jumps.
          <span
            className="grid shrink-0"
            style={{
              gridTemplateColumns: showClear ? "1fr" : "0fr",
              transition: reduced
                ? "none"
                : `grid-template-columns 320ms ${EASE_OUT}`,
            }}
          >
            <span className="min-w-0 overflow-hidden">
              <button
                type="button"
                tabIndex={showClear ? 0 : -1}
                aria-hidden={!showClear}
                aria-label="Clear"
                onClick={() => {
                  if (!inner.current) return;
                  setNativeValue(inner.current, "");
                  inner.current.focus();
                }}
                className={`mr-1 flex items-center justify-center rounded-full text-muted-foreground cursor-pointer hover:bg-accent hover:text-foreground ${sm ? "size-5" : "size-7"} ${INTERACTION_FOCUS}`}
                style={interactionIcon(showClear, reduced)}
              >
                <ClearIcon />
              </button>
            </span>
          </span>
        )}
        {trailing && (
          <span
            className={`flex shrink-0 items-center text-muted-foreground ${sm ? "pr-1" : "pr-1.5"} [&_svg]:size-3.5`}
          >
            {trailing}
          </span>
        )}
      </div>
    </Field>
  );
}

export default Input;

"use client";

import * as React from "react";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * FIELD: the column every text control sits in
 *
 *   label    above, with an optional aside on the right (a count)
 *   hint     under the control while all is well
 *   error    takes the hint's place: the hint folds away, the
 *            error rises in out of a blur, the control shakes once
 *
 * Shared by input, textarea, password, search and select so the
 * whole family has one surface, one focus ring and one error.
 * ───────────────────────────────────────────────────────── */

export interface FieldProps {
  id: string;
  label?: React.ReactNode;
  /** Right side of the label row, e.g. a character count. */
  aside?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  required?: boolean;
  className?: string;
  children: React.ReactNode;
}

export type FieldSize = "sm" | "md";

/** The surface of a text control: a thin line that darkens on hover and turns to the ring on focus. */
export function fieldSurface({
  invalid,
  disabled,
  round = true,
}: {
  invalid?: boolean;
  disabled?: boolean;
  round?: boolean;
}) {
  const ring = invalid
    ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_55%,transparent)] focus-within:shadow-[inset_0_0_0_1px_var(--color-red-500),0_0_0_3px_color-mix(in_oklab,var(--color-red-500)_14%,transparent)]"
    : "shadow-[inset_0_0_0_1px_var(--border)] [&:not(:focus-within)]:hover:shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--foreground)_24%,var(--border))] focus-within:shadow-[inset_0_0_0_1px_var(--ring),0_0_0_3px_color-mix(in_oklab,var(--ring)_16%,transparent)]";
  return `relative flex w-full items-center bg-background text-foreground transition-[box-shadow,background-color,opacity] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] ${round ? "rounded-full" : "rounded-[14px]"} ${ring} ${
    disabled ? "pointer-events-none opacity-50" : ""
  }`;
}

/** ids for the control's label, hint and error. */
export function useFieldIds(id?: string) {
  const auto = React.useId();
  const base = id ?? auto;
  return { id: base, hint: `${base}-hint`, error: `${base}-error` };
}

/** One short shake whenever `on` turns true (an error arrives). */
export function useShake<T extends HTMLElement>(on: boolean) {
  const ref = React.useRef<T>(null);
  const reduced = useInteractionReducedMotion();
  React.useEffect(() => {
    if (!on || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [on, reduced]);
  return ref;
}

/** Sets a native input's value so React's onChange still fires (clear buttons, pickers). */
export function setNativeValue(
  el: HTMLInputElement | HTMLTextAreaElement,
  value: string,
) {
  const proto =
    el instanceof HTMLTextAreaElement
      ? HTMLTextAreaElement.prototype
      : HTMLInputElement.prototype;
  Object.getOwnPropertyDescriptor(proto, "value")?.set?.call(el, value);
  el.dispatchEvent(new Event("input", { bubbles: true }));
}

/** A line under the control that folds open and closed; keeps its last words while closing. */
function Line({
  show,
  children,
  id,
  tone,
  reduced,
}: {
  show: boolean;
  children: React.ReactNode;
  id: string;
  tone: string;
  reduced: boolean;
}) {
  const [kept, setKept] = React.useState(children);
  if (show && children !== kept) setKept(children);
  return (
    <div
      className="grid"
      style={{
        gridTemplateRows: show ? "1fr" : "0fr",
        transition: reduced ? "none" : `grid-template-rows 320ms ${EASE_OUT}`,
      }}
    >
      <div className="min-h-0 overflow-hidden">
        <p
          id={id}
          className={`pt-1.5 pl-3 text-[12.5px] leading-snug ${tone}`}
          style={{
            opacity: show ? 1 : 0,
            filter: show ? "blur(0px)" : "blur(4px)",
            transform: show ? "none" : "translateY(-4px)",
            transition: reduced
              ? "none"
